using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;using Microsoft.EntityFrameworkCore;using BanhangcodeX.Data;using BanhangcodeX.Models;
namespace BanhangcodeX.Controllers;
[ApiController,Route("api/customers"),Authorize] public class CustomersController(AppDbContext db):ControllerBase{[HttpGet]public async Task<IActionResult> List([FromQuery]string? q){var x=db.Customers.AsNoTracking();if(!string.IsNullOrWhiteSpace(q))x=x.Where(c=>c.Name.Contains(q)||c.Code.Contains(q)||(c.Phone!=null&&c.Phone.Contains(q))||(c.ZaloName!=null&&c.ZaloName.Contains(q)));return Ok(await x.OrderBy(c=>c.Name).Take(50).ToListAsync());}[HttpGet("{id:int}")]public async Task<IActionResult> Get(int id){var c=await db.Customers.FindAsync(id);return c==null?NotFound():Ok(c);}[HttpPost]public async Task<IActionResult> Create(Customer c){c.Id=0;c.Code=string.IsNullOrWhiteSpace(c.Code)?$"KH{Guid.NewGuid():N}"[..14]:c.Code;c.CreatedAt=DateTime.UtcNow;c.UpdatedAt=c.CreatedAt;db.Add(c);await db.SaveChangesAsync();return Ok(c);}[HttpPut("{id:int}")]public async Task<IActionResult> Update(int id,Customer i){var c=await db.Customers.FindAsync(id);if(c==null)return NotFound();c.Code=i.Code;c.Name=i.Name;c.Phone=i.Phone;c.ZaloName=i.ZaloName;c.Address=i.Address;c.Note=i.Note;c.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();return Ok(c);}[HttpDelete("{id:int}")]public async Task<IActionResult> Delete(int id){var c=await db.Customers.FindAsync(id);if(c==null)return NotFound();if(await db.Orders.AnyAsync(o=>o.CustomerId==id))return Conflict(new{message="Khách có đơn hàng, không thể xóa hồ sơ."});db.Remove(c);await db.SaveChangesAsync();return NoContent();}[HttpGet("{id:int}/history")]public async Task<IActionResult> History(int id){var x=await db.Orders.AsNoTracking().Include(o=>o.Details).Where(o=>o.CustomerId==id).OrderByDescending(o=>o.OrderDate).ToListAsync();return Ok(new{orders=x,total=x.Sum(o=>o.TotalAmount)});}}
[ApiController,Route("api/products"),Authorize]public class ProductsController(AppDbContext db):ControllerBase{[HttpGet]public async Task<IActionResult> List([FromQuery]string? q){var x=db.Products.AsNoTracking();if(!string.IsNullOrWhiteSpace(q))x=x.Where(p=>p.Name.Contains(q)||p.Code.Contains(q));return Ok(await x.OrderBy(p=>p.Name).ThenBy(p=>p.Size).Take(500).ToListAsync());}[HttpGet("{id:int}")]public async Task<IActionResult> Get(int id){var p=await db.Products.FindAsync(id);return p==null?NotFound():Ok(p);}[HttpPost]public async Task<IActionResult> Create(Product p){p.Id=0;p.Code=string.IsNullOrWhiteSpace(p.Code)?$"SP{Guid.NewGuid():N}"[..14]:p.Code;p.CreatedAt=DateTime.UtcNow;p.UpdatedAt=p.CreatedAt;db.Add(p);await db.SaveChangesAsync();return Ok(p);}[HttpPut("{id:int}")]public async Task<IActionResult> Update(int id,Product i){var p=await db.Products.FindAsync(id);if(p==null)return NotFound();p.Code=i.Code;p.Name=i.Name;p.Color=i.Color;p.Size=i.Size;p.Price=i.Price;p.Stock=i.Stock;p.Note=i.Note;p.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();return Ok(p);}[HttpDelete("{id:int}")]public async Task<IActionResult> Delete(int id){var p=await db.Products.FindAsync(id);if(p==null)return NotFound();db.Remove(p);await db.SaveChangesAsync();return NoContent();}}
